            sh:focusNode [ a schema1:Product,
                        schema1:Thing,
                        prov:Entity ;
                    schema1:additionalProperty [ a schema1:PropertyValue ;
                            schema1:name "Probe" ;
                            schema1:propertyID <https://w3id.org/cdif/xas/probe> ;
                            schema1:value "x-ray" ],
                        [ a schema1:PropertyValue ;
